using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class CP6Editor{static EditorWindow view;static bool started,save,extra;static double deadline;static string root;public static void Run(){Begin(false);}public static void Save(){Begin(true);}public static void Extra(){Begin(false,true);}static void Begin(bool value,bool more=false){save=value;extra=more;root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);deadline=EditorApplication.timeSinceStartup+300;view=UI01Before.Size(1280,720);EditorSceneManager.playModeStartScene=null;EditorSceneManager.OpenScene(GameEntry.TitlePath);EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}static void Tick(){try{EditorApplication.QueuePlayerLoopUpdate();view?.Repaint();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("CP6 bounded deadline");if(!EditorApplication.isPlaying)return;if(!started){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!=GameEntry.TitlePath)return;if(!save)CP05Training.StartIsolated();var go=new GameObject("CP6 Editor probe");UnityEngine.Object.DontDestroyOnLoad(go);var probe=go.AddComponent<CP6Probe>();probe.save=save;probe.extra=extra;started=true;}if(CP6Probe.Done){EditorApplication.update-=Tick;EditorApplication.Exit(CP6Probe.Code);}}catch(Exception e){File.WriteAllText(root+"/exception.txt",e.ToString());EditorApplication.update-=Tick;EditorApplication.Exit(1);}}}
